async function foldArchive(chunks, initial, reduce) {
  const decoder = new TextDecoder("utf-8", {
    fatal: true,
    ignoreBOM: true
  });

  const iterator = chunks[Symbol.asyncIterator]();
  const pending = [];
  let pendingLength = 0;
  let physicalLine = 1;
  let recordIndex = 0;
  let state = initial;
  let reachedEOF = false;
  let closed = false;

  async function closeIterator() {
    if (closed || reachedEOF) return;
    closed = true;

    const returnMethod = iterator.return;
    if (typeof returnMethod === "function") {
      await returnMethod.call(iterator);
    }
  }

  function saveTail(chunk, start) {
    const length = chunk.length - start;
    if (length === 0) return;

    const copy = new Uint8Array(length);
    copy.set(chunk.subarray(start));
    pending.push(copy);
    pendingLength += length;
  }

  function assembleLine(chunk, start, end) {
    const tailLength = end - start;

    if (pendingLength === 0) {
      return chunk.subarray(start, end);
    }

    const line = new Uint8Array(pendingLength + tailLength);
    let offset = 0;

    for (const part of pending) {
      line.set(part, offset);
      offset += part.length;
    }

    line.set(chunk.subarray(start, end), offset);
    pending.length = 0;
    pendingLength = 0;
    return line;
  }

  function assembleFinalLine() {
    if (pending.length === 1) {
      const line = pending[0];
      pending.length = 0;
      pendingLength = 0;
      return line;
    }

    const line = new Uint8Array(pendingLength);
    let offset = 0;

    for (const part of pending) {
      line.set(part, offset);
      offset += part.length;
    }

    pending.length = 0;
    pendingLength = 0;
    return line;
  }

  async function processLine(bytes, lineNumber) {
    if (bytes.length > 0 && bytes[bytes.length - 1] === 13) {
      bytes = bytes.subarray(0, bytes.length - 1);
    }

    const text = decoder.decode(bytes);
    if (text.trim().length === 0) return false;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      return false;
    }

    const result = await reduce(state, value, {
      physicalLine: lineNumber,
      recordIndex
    });

    state = result.state;
    recordIndex += 1;
    return result.done;
  }

  try {
    while (true) {
      const item = await iterator.next();

      if (item.done) {
        reachedEOF = true;
        break;
      }

      const chunk = item.value;
      let start = 0;

      for (let index = 0; index < chunk.length; index += 1) {
        if (chunk[index] !== 10) continue;

        const line = assembleLine(chunk, start, index);
        const done = await processLine(line, physicalLine);
        physicalLine += 1;
        start = index + 1;

        if (done) {
          await closeIterator();
          return state;
        }
      }

      saveTail(chunk, start);
    }

    if (pendingLength > 0) {
      const line = assembleFinalLine();
      await processLine(line, physicalLine);
    }

    return state;
  } catch (error) {
    if (!reachedEOF) {
      try {
        await closeIterator();
      } catch {
        // Preserve the original read or reducer error.
      }
    }

    throw error;
  }
}
